public class Exercise {
    static String[] DATA = {"alpha", "beta", "gamma", "delta"};

    public static String processInput(String s) {
        try {
            int index = Integer.parseInt(s);
            return DATA[index];
        } catch (NumberFormatException | ArrayIndexOutOfBoundsException e) {
            // Multi-catch: handles either exception with the same handler
            return "Error (" + e.getClass().getSimpleName() + "): " + e.getMessage();
        }
    }

    // Demonstrating catch ordering: specific before general
    public static void catchOrdering(String s) {
        try {
            int x = Integer.parseInt(s);
            System.out.println("Parsed: " + x);
        } catch (NumberFormatException e) {
            System.out.println("Specific: not a number -> " + e.getMessage());
        } catch (RuntimeException e) {
            // Would catch any other RuntimeException not caught above
            System.out.println("General RuntimeException: " + e.getMessage());
        } catch (Exception e) {
            System.out.println("Most general: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        System.out.println(processInput("1"));   // beta
        System.out.println(processInput("99"));  // Error (ArrayIndexOutOfBoundsException): ...
        System.out.println(processInput("abc")); // Error (NumberFormatException): ...
        catchOrdering("42");
        catchOrdering("oops");
    }
}

