public class Exercise {
    static class MyResource implements AutoCloseable {
        private final String name;
        MyResource(String name) {
            this.name = name;
            System.out.println("Opened: " + name);
        }
        public void use() { System.out.println("Using: " + name); }
        @Override
        public void close() {
            System.out.println("Closed: " + name);
        }
    }

    public static void main(String[] args) {
        System.out.println("--- Single resource ---");
        try (MyResource r = new MyResource("R1")) {
            r.use();
        } // close() called automatically here

        System.out.println();
        System.out.println("--- Multiple resources (closed in reverse order) ---");
        try (MyResource r1 = new MyResource("A");
             MyResource r2 = new MyResource("B")) {
            r1.use();
            r2.use();
        } // B closed first, then A

        System.out.println();
        System.out.println("--- Resource with exception ---");
        try (MyResource r = new MyResource("ExResource")) {
            r.use();
            if (true) throw new RuntimeException("Something went wrong");
            r.use(); // not reached
        } catch (RuntimeException e) {
            System.out.println("Caught: " + e.getMessage());
        }
        // Output: Opened, Using, Closed (before catch block), Caught
    }
}

