public class Exercise {
    static class FailingResource implements AutoCloseable {
        @Override
        public void close() throws Exception {
            System.out.println("close() throwing...");
            throw new Exception("Error during close");
        }
    }

    public static void main(String[] args) {
        try (FailingResource res = new FailingResource()) {
            System.out.println("In try body, throwing...");
            throw new RuntimeException("Primary exception from try body");
        } catch (Exception e) {
            System.out.println("Primary: " + e.getMessage());
            Throwable[] suppressed = e.getSuppressed();
            System.out.println("Suppressed count: " + suppressed.length); // 1
            for (Throwable s : suppressed) {
                System.out.println("Suppressed: " + s.getMessage()); // Error during close
            }
        }

        // Contrast: without try-with-resources (old style), close() exception swallows body exception:
        System.out.println();
        System.out.println("If you did it manually with finally:");
        System.out.println("  the body exception would be LOST if finally also throws!");
    }
}

