public class Exercise {
    static class InsufficientFundsException extends Exception {
        private final double amount;
        private final double balance;

        InsufficientFundsException(double amount, double balance) {
            super(String.format("Insufficient funds: attempted to withdraw %.2f but balance is %.2f",
                               amount, balance));
            this.amount  = amount;
            this.balance = balance;
        }

        public double getAmount()  { return amount; }
        public double getBalance() { return balance; }
    }

    static class BankAccount {
        private double balance;
        BankAccount(double balance) { this.balance = balance; }

        public void withdraw(double amount) throws InsufficientFundsException {
            if (amount > balance) {
                throw new InsufficientFundsException(amount, balance);
            }
            balance -= amount;
            System.out.println("Withdrew " + amount + ", new balance: " + balance);
        }
    }

    public static void main(String[] args) {
        BankAccount account = new BankAccount(100.0);
        try {
            account.withdraw(40.0);
            account.withdraw(80.0); // will fail
        } catch (InsufficientFundsException e) {
            System.out.println("Caught: " + e.getMessage());
            System.out.println("Tried: " + e.getAmount() + ", had: " + e.getBalance());
        }
    }
}

