                    // Simulate a DB driver throwing a low-level exception
                    throw new IllegalArgumentException("DB error: invalid id " + id);
                }
                if (id > 100) {
                    throw new RuntimeException("DB connection lost");
                }
                return "User-" + id;
            } catch (IllegalArgumentException | RuntimeException e) {
                // Wrap low-level exception in domain exception
                throw new DatabaseException("Failed to find user with id=" + id, e);
