public class Exercise {
    static class DataAccessException extends Exception {
        DataAccessException(String msg, Throwable cause) { super(msg, cause); }
    }
    static class ServiceException extends Exception {
        ServiceException(String msg, Throwable cause) { super(msg, cause); }
    }
    static class ControllerException extends Exception {
        ControllerException(String msg, Throwable cause) { super(msg, cause); }
    }

    static class Dao {
        void fetchData() throws DataAccessException {
            try {
                throw new RuntimeException("SQL: connection refused");
            } catch (RuntimeException e) {
                throw new DataAccessException("DAO: failed to fetch data", e);
            }
        }
    }

    static class Service {
        Dao dao = new Dao();
        void processData() throws ServiceException {
            try {
                dao.fetchData();
            } catch (DataAccessException e) {
                throw new ServiceException("Service: data processing failed", e);
            }
        }
    }

    static class Controller {
        Service service = new Service();
        void handleRequest() throws ControllerException {
            try {
                service.processData();
            } catch (ServiceException e) {
                throw new ControllerException("Controller: request handling failed", e);
            }
        }
    }

    static void printCauseChain(Throwable t) {
        int depth = 0;
        while (t != null) {
            System.out.println("  ".repeat(depth) + t.getClass().getSimpleName() + ": " + t.getMessage());
            t = t.getCause();
            depth++;
        }
    }

    public static void main(String[] args) {
        try {
            new Controller().handleRequest();
        } catch (ControllerException e) {
            System.out.println("Caught at top level:");
            printCauseChain(e);
        }
    }
}

