public class Exercise {
    // Anti-pattern 1: catching Exception blindly
    static void badPattern1(String s) {
        try {
            int x = Integer.parseInt(s);
            System.out.println("Parsed: " + x);
        } catch (Exception e) { // Too broad! Also catches NullPointerException, OutOfMemoryError...
            System.out.println("Something failed: " + e.getMessage());
            // Problem: we don't know what failed or why; also masks programming errors
        }
    }

    // Anti-pattern 2: empty catch (swallowing)
    static void badPattern2(String s) {
        try {
            int x = Integer.parseInt(s);
        } catch (NumberFormatException e) {
            // !! Silent: the exception is lost; caller thinks everything is fine
        }
    }

    // Anti-pattern 3: losing the cause
    static void badPattern3(String s) throws IllegalArgumentException {
        try {
            int x = Integer.parseInt(s);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Bad input: " + s); // cause e is dropped!
        }
    }

    // Good pattern: catch specifically, log context, preserve cause
    static void goodPattern(String s) throws IllegalArgumentException {
        try {
            int x = Integer.parseInt(s);
            System.out.println("Processed: " + x);
        } catch (NumberFormatException e) {
            // Log with full context (in production: use a real logger)
            System.err.println("[ERROR] Could not parse integer from input='" + s + "': " + e.getMessage());
            // Rethrow with cause preserved
            throw new IllegalArgumentException("Invalid integer input: '" + s + "'", e);
        }
    }

    public static void main(String[] args) {
        badPattern1("oops");  // catches too broadly
        badPattern2("oops");  // silent failure

        try {
            goodPattern("42");    // success
            goodPattern("bad");   // throws, with cause
        } catch (IllegalArgumentException e) {
            System.out.println("Caught: " + e.getMessage());
            System.out.println("Root cause: " + e.getCause().getMessage());
        }
    }
}

