public class Exercise {
    static class Connection implements AutoCloseable {
        String name;
        Connection(String name) { this.name = name; System.out.println("Open: " + name); }
        public void query() { System.out.println("Query on " + name); }
        public void close() { System.out.println("Close: " + name); }
    }

    static void processOldWay() throws Exception {
        Connection c1 = null;
        Connection c2 = null;
        try {
            c1 = new Connection("DB");
            c2 = new Connection("Cache");
            c1.query();
            c2.query();
            // Simulate error:
            // throw new Exception("processing error");
        } finally {
            // Null-check before closing; close c2 before c1 (reverse order)
            if (c2 != null) {
                try { c2.close(); } catch (Exception e) {
                    System.err.println("Error closing c2: " + e.getMessage());
                }
            }
            if (c1 != null) {
                try { c1.close(); } catch (Exception e) {
                    System.err.println("Error closing c1: " + e.getMessage());
                }
            }
        }
    }

    static void processNewWay() throws Exception {
        try (Connection c1 = new Connection("DB");
             Connection c2 = new Connection("Cache")) {
            c1.query();
            c2.query();
        } // c2 closed first, then c1 — automatically, correctly
    }

    public static void main(String[] args) throws Exception {
        System.out.println("--- Old way ---");
        processOldWay();
        System.out.println();
        System.out.println("--- New way ---");
        processNewWay();
