import java.io.IOException;

public class Exercise {
    // Option 1: propagate throws declarations up the call chain
    static void methodC_option1() throws IOException {
        System.out.println("C1: throwing");
        throw new IOException("Simulated IO failure");
    }
    static void methodB_option1() throws IOException {
        System.out.println("B1: calling C");
        methodC_option1(); // must declare throws because C declares it
    }
    static void methodA_option1() throws IOException {
        System.out.println("A1: calling B");
        methodB_option1(); // must declare throws because B declares it
    }

    // Option 2: wrap at the service boundary (B is the boundary)
    static void methodC_option2() throws IOException {
        System.out.println("C2: throwing");
        throw new IOException("Simulated IO failure");
    }
    static void methodB_option2() { // no throws — wraps before propagating
        System.out.println("B2: calling C, catching and wrapping");
        try {
            methodC_option2();
        } catch (IOException e) {
            throw new RuntimeException("Service failure in B", e); // wraps with cause
        }
    }
    static void methodA_option2() { // no throws needed
        System.out.println("A2: calling B");
        methodB_option2();
    }

    public static void main(String[] args) {
        System.out.println("--- Option 1: propagated throws ---");
        try {
            methodA_option1();
        } catch (IOException e) {
            System.out.println("main caught IOException: " + e.getMessage());
        }

        System.out.println();
        System.out.println("--- Option 2: wrapped at boundary ---");
        try {
            methodA_option2();
        } catch (RuntimeException e) {
            System.out.println("main caught RuntimeException: " + e.getMessage());
            System.out.println("Caused by: " + e.getCause().getMessage());
        }
    }
}
